<?php
require_once 'config/auth.php';$page_title='Dashboard';$base='';
$customers=$pdo->query("SELECT COUNT(*) c FROM customers")->fetch()['c'];$leads=$pdo->query("SELECT COUNT(*) c FROM leads WHERE status NOT IN('converted','lost')")->fetch()['c'];$open=$pdo->query("SELECT COUNT(*) c FROM deals WHERE stage NOT IN('won','lost')")->fetch()['c'];$sales=$pdo->query("SELECT COALESCE(SUM(amount),0) s FROM deals WHERE stage='won'")->fetch()['s'];$due=$pdo->query("SELECT COUNT(*) c FROM followups WHERE status='pending' AND due_at<=NOW()")->fetch()['c'];
$recent=$pdo->query("SELECT d.*,c.name customer FROM deals d JOIN customers c ON c.id=d.customer_id ORDER BY d.created_at DESC LIMIT 6")->fetchAll();
$chart=$pdo->query("SELECT DATE_FORMAT(created_at,'%b') m,SUM(amount) total FROM deals WHERE stage='won' AND created_at>=DATE_SUB(CURDATE(),INTERVAL 6 MONTH) GROUP BY YEAR(created_at),MONTH(created_at) ORDER BY YEAR(created_at),MONTH(created_at)")->fetchAll();
$chart_js='<script>new Chart(document.getElementById("salesChart"),{type:"bar",data:{labels:'.json_encode(array_column($chart,'m')).',datasets:[{label:"Won Sales",data:'.json_encode(array_map("floatval",array_column($chart,'total'))).',borderRadius:8}]},options:{plugins:{legend:{display:false}},scales:{y:{beginAtZero:true}}}});</script>';
include 'partials/header.php';?>
<div class="row g-3 mb-4"><?php foreach([['Customers',$customers,'bi-people'],['Open Leads',$leads,'bi-funnel'],['Open Deals',$open,'bi-briefcase'],['Won Sales','$'.number_format($sales,2),'bi-currency-dollar'],['Due Follow-ups',$due,'bi-calendar-check']] as $s):?><div class="col-xl col-md-6"><div class="cardx stat"><div><small class="text-muted"><?=$s[0]?></small><div class="metric"><?=$s[1]?></div></div><div class="stat-icon"><i class="bi <?=$s[2]?>"></i></div></div></div><?php endforeach;?></div>
<div class="row g-4"><div class="col-lg-8"><div class="cardx"><h5>Sales performance</h5><canvas id="salesChart" height="120"></canvas></div></div><div class="col-lg-4"><div class="cardx"><h5>Quick actions</h5><div class="d-grid gap-2 mt-3"><a class="btn btn-primary" href="customers/form.php">+ Add Customer</a><a class="btn btn-outline-primary" href="leads/form.php">+ Add Lead</a><a class="btn btn-outline-primary" href="deals/form.php">+ Create Deal</a><a class="btn btn-outline-primary" href="followups/form.php">+ Schedule Follow-up</a></div></div></div></div>
<div class="cardx mt-4"><h5>Recent deals</h5><div class="table-responsive"><table class="table mt-3"><thead><tr><th>Deal</th><th>Customer</th><th>Amount</th><th>Stage</th></tr></thead><tbody><?php foreach($recent as $r):?><tr><td><?=e($r['title'])?></td><td><?=e($r['customer'])?></td><td>$<?=number_format($r['amount'],2)?></td><td><span class="status"><?=e(ucfirst($r['stage']))?></span></td></tr><?php endforeach;?></tbody></table></div></div><?php include 'partials/footer.php';?>